fn solve(s: &Vec<char>) -> Vec<char> {
    // Clone the original word into a new Vec<char>
    let mut result = s.clone();

    // If the word ends with 's', append "es", otherwise append "s"
    if let Some(&last_char) = s.last() {
        if last_char == 's' {
            result.push('e');
            result.push('s');
        } else {
            result.push('s');
        }
    }

    result
}

